 if(action==='save-skill'){if(!project)return;download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),project.slug+'.agentic.json');notify('Skill backup prepared, including source originals.');return;}
 if(action==='new'){newSkillMode='prompt';newSkillInput={prompt:'',title:'',slug:'',description:''};pendingDraft=null;openDialog('new');return;}
 if(action==='optimize-after-import'){const incoming=pendingImport,destination=pendingImportProjectId;if(!incoming)return;replaceProject(incoming,'Imported source added. Create a separate optimized version.',destination);pendingImport=null;pendingImportProjectId='';importRequestToken++;openDialog('optimize');return;}
 if(action==='refine-optimization'){pendingOptimization=null;pendingOptimizationProjectId='';openDialog('optimize');return;}
 if(action==='download-optimization-baseline'){download(new Blob([JSON.stringify(project.optimization.baseline,null,2)],{type:'application/json'}),project.slug+'-baseline.agentic.json');return;}
 if(action==='open-optimization-source'){const id=project.optimization.sourceId;closeDialog();openWorkspaceSkill(activeProjectId,id);return;}
