 if(action==='download-source'){try{const resource=project.originals.find(o=>o.path===b.dataset.path);download(new Blob([sourceBytes(resource)],{type:'application/octet-stream'}),resource.path.split('/').at(-1));}catch(error){notify(error.message,true);}return;}
 if(action==='download-originals'){try{const folder=(slugify(project.slug)||'original-skill')+'/';download(writeZip(Object.fromEntries(project.originals.map(o=>[o.archivePath||folder+o.path,sourceBytes(o)]))),(slugify(project.slug)||'original-skill')+'-source-originals.zip');notify('Original source bundle prepared with all retained file contents.');}catch(error){notify(error.message,true);}return;}

