 if(action==='resource-source'){const resource=project.resources.find(r=>r.id===b.dataset.id),original=project.originals.find(o=>o.path===resource.sourcePath);if(!original){notify('This package contains the English specification. Original code is kept in its separate source archive.',true);return;}openDialog('originals');return;}
 if(action==='definitions'){page='references';referenceTab='definitions';render();return;}
