 if(action==='move-up'||action==='move-down'){if(b.dataset.id)selected=b.dataset.id;mutate(()=>{const i=project.steps.indexOf(step()),to=i+(action==='move-up'?-1:1);if(to>=0&&to<project.steps.length){const [s]=project.steps.splice(i,1);project.steps.splice(to,0,s);}},'Step order updated. Review the steps with changed inputs.',{orderChange:true});return;}
 if(action==='approve'){const s=step();if(!s.job.trim()||!s.output.trim()||!project.input.trim()){tab='definition';render();notify('Define the overall input and this step’s instructions and output before confirming the proposal.',true);return;}mutate(()=>s.reviewed=true,project.generation||project.optimization?'Proposed step confirmed.':'Imported step confirmed.');return;}
 if(action==='clear-override'){mutate(()=>step().facets.find(f=>f.id===b.dataset.id).override='','Facet now follows the shared definition.');return;}
 if(action==='remove-facet'){mutate(()=>{step().facets=step().facets.filter(f=>f.id!==b.dataset.id);tab='facets';},'Facet removed. Undo can restore it.');closeDialog();return;}
 if(action==='remove-reference'){mutate(()=>{project.references=project.references.filter(r=>r.id!==b.dataset.id);referenceId=project.references[0]?.id||'';},'Reference removed. Missing dependencies appear in review.');return;}
 if(action==='remove-definition'){mutate(()=>project.definitions=project.definitions.filter(d=>d.id!==b.dataset.id),'Definition removed. Linked facets need review.');return;}
